INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (165, 1, 'cron 5개 필드', '`*/5 9-18 * * 1-5 echo hi` 에서 다섯 개 필드의 순서와 이 줄의 뜻은 무엇일까요?', '분, 시, 일, 월, 요일 순서예요.', NULL, NULL, '[]', 'choice', '["순서는 초 분 시 일 월이고, 매일 5분마다 실행한다", "순서는 요일 월 일 시 분이고, 한 번만 실행한다", "순서는 분 시 일 월 요일이고, 평일(월~금) 9시~18시 사이에 5분마다 실행한다는 뜻이다", "순서는 시 분 일 월 요일이고, 9시와 18시에만 실행한다"]', 2, '필드 순서를 모르면 시간을 잘못 읽습니다. 첫 두 칸이 `분 시` 라는 것을 가장 먼저 외우세요.', NULL, NULL, NULL, NULL),
  (165, 2, '*, */n, 범위, 목록', 'cron 에서 `*`, `*/5`, `1-5`, `1,15` 는 각각 무엇을 뜻할까요?', '모두, 단계, 범위, 목록이에요.', NULL, NULL, '[]', 'choice', '["`*` 는 곱하기, `*/5` 는 나누기, `1-5` 는 빼기, `1,15` 는 소수", "`*` 는 모든 값, `*/5` 는 5 단위마다, `1-5` 는 1부터 5까지, `1,15` 는 1 과 15 (쉼표로 나열)", "모두 같은 뜻이다", "`1,15` 는 1부터 15까지이다"]', 1, '`0 3 * * *` 는 매일 3시 0분, `0 3 1,15 * *` 는 매월 1일과 15일 3시입니다. `1,15` 와 `1-15` 를 혼동하지 마세요.', NULL, NULL, NULL, NULL),
  (165, 3, '요일 숫자', 'cron 의 요일 필드에서 숫자는 어떻게 읽을까요? (`date +%w` 도 같은 방식입니다)', '일요일이 0 이에요.', NULL, NULL, '[]', 'choice', '["0 이 일요일(7 도 일요일), 1 이 월요일 … 6 이 토요일이다", "1 이 일요일, 7 이 토요일이다", "0 이 월요일, 6 이 일요일이다", "숫자는 쓸 수 없고 이름만 가능하다"]', 0, '`date +%u` 는 월요일이 1, 일요일이 7 인 ISO 방식이라 `%w` 와 다릅니다. 2026-10-31(토)은 `%w` 가 6, `%u` 도 6 이에요.', NULL, NULL, NULL, NULL),
  (165, 4, '일과 요일을 모두 지정하면', '`0 3 15 * 1 backup.sh` 처럼 일 필드(15)와 요일 필드(1, 월)를 둘 다 지정하면 언제 실행될까요?', '둘 다 맞아야 할 것 같지만 실제로는 달라요.', NULL, NULL, '[]', 'choice', '["15일이면서 월요일인 날에만 실행한다", "15일에만 실행하고 요일은 무시한다", "월요일에만 실행하고 일은 무시한다", "일 또는 요일 중 하나만 맞아도 실행한다 (OR). 이 줄은 매월 15일과 모든 월요일의 3시에 실행된다"]', 3, '한쪽 필드만 지정하고 다른 쪽은 `*` 로 두는 것이 안전합니다. 실제 실행으로 "일만 맞음", "요일만 맞음" 줄이 모두 실행되는 것을 확인했어요.', NULL, NULL, NULL, NULL),
  (165, 5, 'cron 의 PATH', '터미널에서는 되는 명령이 cron 에서는 `not found`(종료 코드 127)가 납니다. 흔한 원인과 해결은 무엇일까요?', 'cron 은 로그인 쉘과 환경이 달라요.', NULL, NULL, '[]', 'choice', '["cron 에서는 쉘 명령을 쓸 수 없다", "서버를 재부팅하면 해결된다", "cron 의 `PATH` 는 `/usr/bin:/bin` 정도로 짧아서 다른 폴더의 명령을 못 찾는다. 명령을 절대 경로로 쓰거나 crontab 위쪽에 `PATH=...` 를 정의한다", "명령 이름을 대문자로 쓴다"]', 2, '`which 명령` 으로 절대 경로를 찾아 적으세요. 실제로 cron 안에서 `PATH=/usr/bin:/bin` 이 출력되는 것을 확인했습니다.', NULL, NULL, NULL, NULL),
  (165, 6, 'cron 이 쓰는 쉘', 'cron 의 줄은 어떤 쉘로 실행될까요? (기본값)', '로그인 쉘(bash)이 아니라 더 단순한 쉘이에요.', NULL, NULL, '[]', 'choice', '["항상 사용자의 로그인 쉘(bash)로 실행된다", "`/bin/sh` 로 실행된다 (`SHELL=/bin/sh`). bash 전용 문법은 기본 설정에서 동작하지 않을 수 있다", "쉘 없이 직접 프로그램만 실행한다", "항상 zsh 로 실행된다"]', 1, '필요하면 crontab 위쪽에 `SHELL=/bin/bash` 를 적습니다. 스크립트 안에서는 맨 윗줄의 `#!/bin/bash` 를 쓰면 그 쉘이 쓰여요.', NULL, NULL, NULL, NULL),
  (165, 7, 'crontab 의 % 기호', 'crontab 줄 `* * * * * date +%Y > /tmp/year.log` 가 의도대로 동작하지 않습니다. 왜일까요?', '%는 cron 에서 특별한 의미가 있어요.', NULL, NULL, '[]', 'choice', '["crontab 에서 `%` 는 줄바꿈으로 해석되어 명령이 `date +` 에서 끊기고 뒤쪽은 표준 입력이 되므로 리다이렉트도 적용되지 않는다. `date +\\\\%Y` 처럼 `\\\\` 로 이스케이프해야 한다", "`date` 명령이 cron 에서 지원되지 않는다", "`>` 기호는 cron 에서 쓸 수 없다", "연도는 `%Y` 가 아니라 `%y` 만 쓸 수 있다"]', 0, '실제로 이스케이프하지 않은 줄은 출력 파일이 아예 만들어지지 않았고, `\\%Y` 는 `2026` 이 기록됐습니다. 날짜가 든 파일 이름을 만들 때 자주 만나는 함정이에요.', NULL, NULL, NULL, NULL),
  (165, 8, 'cron 작업의 출력', 'cron 줄 `* * * * * backup.sh` 의 출력(표준 출력과 오류)은 어디로 갈까요? 로그를 남기려면 어떻게 할까요?', '터미널이 없어요.', NULL, NULL, '[]', 'choice', '["자동으로 화면에 보인다", "항상 `/var/log/cron.log` 에 저장된다", "출력이 있으면 작업이 실패한다", "리다이렉트가 없으면 메일(보통 메일 서버가 없으면 사라짐)로 가므로 `>> /var/log/backup.log 2>&1` 처럼 파일에 이어 붙이도록 직접 적는다"]', 3, '`>` 는 실행할 때마다 덮어쓰고 `>>` 는 이어 붙입니다. `2>&1` 을 빼면 오류가 남지 않아요.', NULL, NULL, NULL, NULL),
  (165, 9, 'cron 작업의 작업 디렉터리', 'cron 줄 `* * * * * pwd > /tmp/cwd.out` 이 기록하는 현재 폴더는 어디일까요? (root 계정)', '로그인할 때의 기본 위치예요.', NULL, NULL, '[]', 'choice', '["항상 `/` 이다", "스크립트가 있는 폴더이다", "사용자의 홈 폴더(`/root`)이다. 다른 폴더의 상대 경로를 쓰려면 `cd /path && ...` 로 먼저 이동하거나 절대 경로를 쓴다", "마지막으로 이동한 폴더이다"]', 2, '상대 경로 때문에 터미널에서는 되고 cron 에서는 실패하는 경우가 흔합니다. 경로는 절대 경로로 쓰세요.', NULL, NULL, NULL, NULL),
  (165, 10, 'crontab 파일의 마지막 줄', '`crontab 파일` 로 등록하려는데 `new crontab file is missing newline before EOF, can''t install.` 오류가 납니다. 원인은 무엇일까요?', '파일 끝에 필요한 한 가지가 빠졌어요.', NULL, NULL, '[]', 'choice', '["필드가 6개를 넘었다", "파일의 마지막 줄 끝에 줄바꿈 문자가 없다. 마지막 줄 뒤에 Enter 를 쳐서 줄바꿈을 넣으면 해결된다", "root 권한이 없다", "분 필드가 60 이다"]', 1, '에디터로 `crontab -e` 를 쓰면 보통 자동으로 처리되지만 파일을 직접 만들 때 자주 빠집니다. 이 오류는 종료 코드 1 로 설치를 막아요.', NULL, NULL, NULL, NULL),
  (165, 11, '에포크 초와 날짜 변환', '`date +%s` 와 `date -u -d @0 ''+%F %T''` 는 각각 무엇을 출력할까요?', '1970년 1월 1일을 기준으로 센 초예요.', NULL, NULL, '[]', 'choice', '["`%s` 는 1970-01-01 00:00:00 UTC 부터 지난 초(에포크)이고, `-d @0` 은 에포크 0 초를 날짜로 바꿔 `1970-01-01 00:00:00` 을 출력한다", "`%s` 는 현재 초(0~59), `-d @0` 은 오늘 자정이다", "`%s` 는 시간대 이름이고 `@0` 은 오류이다", "둘 다 현재 시각을 출력한다"]', 0, '두 날짜의 에포크를 빼서 86400(하루의 초)으로 나누면 일수가 나옵니다. 실제로 2026-03-01 과 2026-02-01 의 차이는 28일이에요.', NULL, NULL, NULL, NULL),
  (165, 12, 'date 로 날짜 계산', '`date -u -d ''2024-02-28 +1 day'' +%F` 와 `date -d ''2026-02-30''` 은 각각 어떻게 될까요?', '윤년과 없는 날짜를 생각해 보세요.', NULL, NULL, '[]', 'choice', '["앞은 `2024-03-01`, 뒤는 `2026-03-02` 로 보정된다", "둘 다 오류가 난다", "둘 다 입력값을 그대로 출력한다", "앞은 윤년이라 `2024-02-29` 를 출력하고, 뒤는 존재하지 않는 날짜라 `invalid date` 오류가 난다"]', 3, '`-d ''어제''`, `-d ''2026-03-01 -1 day''` 같은 표현으로 백업 파일의 보관 기한 날짜를 구할 수 있습니다.', NULL, NULL, NULL, NULL),
  (165, 13, 'POSIX TZ 의 부호', '`TZ=KST-9 date +%z` 는 `+0900` 이고 `TZ=EST5 date +%z` 는 `-0500` 입니다. 이 부호 방식에 대한 설명으로 알맞은 것은 무엇일까요?', 'UTC 보다 앞선 시간대가 오히려 음수로 적혀요.', NULL, NULL, '[]', 'choice', '["부호가 일반 표기와 같다", "`TZ` 형식은 숫자를 쓸 수 없다", "POSIX 형식의 `TZ` 는 UTC 와의 차이를 반대 부호로 적는다. UTC 보다 9시간 빠른 한국은 `KST-9`, 5시간 늦은 미국 동부는 `EST5` 이다", "`KST-9` 는 UTC 보다 9시간 늦다는 뜻이다"]', 2, '`date -u` 는 항상 UTC 로 출력합니다. 서버의 시간대 설정과 cron 의 실행 시각이 어긋나는 문제를 풀 때 이 부호를 알아 두세요.', NULL, NULL, NULL, NULL),
  (165, 14, 'timeout 으로 멈춤 방지', '`timeout 1 sleep 5` 를 실행하고 `echo $?` 를 하면 무엇이 나올까요? 이 명령이 cron 에서 유용한 이유는 무엇일까요?', '시간이 지나면 강제로 종료돼요.', NULL, NULL, '[]', 'choice', '["`0` 이 나오고 5초를 모두 기다린다", "`124` 가 나온다 (시간 초과로 종료됨). 멈춘 작업이 계속 겹쳐 쌓이는 것을 막으려고 cron 작업을 `timeout 600 작업` 처럼 감쌀 수 있다", "`1` 이 나오고 즉시 오류가 난다", "`124` 는 sleep 이 정상 종료했다는 뜻이다"]', 1, '실행 주기보다 작업이 오래 걸리면 같은 작업이 겹쳐 돌 수 있습니다. 정해진 시간 안에 끝나지 않으면 멈추도록 해 두세요.', NULL, NULL, NULL, NULL),
  (165, 15, '매일 3시 정각의 분 필드', '`backup.sh` 를 **매일 3시 0분**에 실행하려고 합니다. 첫 필드(분)를 채우세요.', '정각이니 0분이에요.', NULL, NULL, '[]', 'fill', '["0", "3", "*", "*/3"]', NULL, '`3 * * * *` 처럼 쓰면 매시 3분에 실행됩니다. 첫 칸이 분이라는 것을 기억하세요.', '[0]', '{0} 3 * * * /usr/local/bin/backup.sh', NULL, NULL),
  (165, 16, '5분마다', '**5분마다** 실행하려고 합니다. `*/` 뒤의 숫자를 채우세요.', '단계 숫자예요.', NULL, NULL, '[]', 'fill', '["5", "05", "5m", "/5"]', NULL, '`*/5` 는 0, 5, 10, … 분에 실행됩니다. 단위(`m`)는 쓰지 않아요.', '[0]', '*/{0} * * * * check.sh', NULL, NULL),
  (165, 17, '평일만', '**월요일부터 금요일**까지만 실행하려고 합니다. 요일 필드를 채우세요.', '월요일은 1, 금요일은 5 예요.', NULL, NULL, '[]', 'fill', '["1-5", "1~5", "5-1", "1:5"]', NULL, '범위는 하이픈으로 씁니다. `0-5` 는 일요일부터 금요일까지가 돼요.', '[0]', '0 9 * * {0} report.sh', NULL, NULL),
  (165, 18, '특정 일 두 개', '매월 **1일과 15일**에만 실행하려고 합니다. 일 필드를 채우세요.', '쉼표로 나열해요.', NULL, NULL, '[]', 'fill', '["1,15", "1-15", "1/15", "1&15"]', NULL, '`1-15` 는 1일부터 15일까지 매일입니다. 날짜가 따로 떨어져 있으면 쉼표를 쓰세요.', '[0]', '0 3 {0} * * payroll.sh', NULL, NULL),
  (165, 19, '% 이스케이프', 'crontab 줄에서 `date +` 뒤의 **퍼센트(`%Y`의 `%`)가 줄바꿈으로 해석되지 않게** 이스케이프하는 기호를 채우세요.', '역슬래시예요.', NULL, NULL, '[]', 'fill', '["\\\\%", "%", "$", "&"]', NULL, 'crontab 에서 `%` 는 줄바꿈입니다. 이스케이프하지 않으면 명령이 끊기고 리다이렉트도 적용되지 않아요.', '[0]', '* * * * * date +{0}Y > /tmp/year.log', NULL, NULL),
  (165, 20, '로그에 이어 붙이기', 'cron 작업의 출력을 로그에 **이어서 기록**하려고 합니다. 리다이렉트 기호를 채우세요.', '화살표가 두 개예요.', NULL, NULL, '[]', 'fill', '[">>", ">", "|", "&"]', NULL, '`>` 는 실행할 때마다 덮어씁니다. `2>&1` 을 함께 써야 오류도 같은 파일에 남아요.', '[0]', '* * * * * /usr/local/bin/backup.sh {0} /var/log/backup.log 2>&1', NULL, NULL),
  (165, 21, '등록된 cron 보기', '현재 사용자의 **등록된 cron 목록**을 보는 옵션을 채우세요.', 'list 의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-l", "-e", "-r", "-v"]', NULL, '등록된 것이 없으면 `no crontab for 사용자` 가 나옵니다. `-e` 는 편집, `-r` 은 삭제예요.', '[0]', 'crontab {0}', NULL, NULL),
  (165, 22, 'cron 전체 삭제', '현재 사용자의 **cron 을 모두 삭제**하는 옵션을 채우세요. (확인 없이 지워집니다)', 'remove 의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["-r", "-d", "-x", "-l"]', NULL, '삭제 전에 `crontab -l > backup.cron` 으로 백업해 두세요. 한 줄만 지우는 옵션은 없어요.', '[0]', 'crontab {0}', NULL, NULL),
  (165, 23, '에포크 0 을 날짜로', '에포크 **0 초가 어떤 날짜인지** UTC 로 출력하려고 합니다. 인자를 채우세요.', '에포크 초 앞에 붙이는 기호가 필요해요.', NULL, NULL, '[]', 'fill', '["@0", "0", "epoch:0", "#0"]', NULL, '`@` 뒤의 숫자를 에포크 초로 읽습니다. 로그의 타임스탬프를 사람이 읽는 날짜로 바꿀 때 씁니다.', '[0]', 'date -u -d {0} ''+%F %T''', NULL, NULL),
  (165, 24, '에포크 초 출력', '현재 시각을 **에포크 초**로 출력하는 형식을 채우세요.', 'second 의 첫 글자입니다. 소문자예요.', NULL, NULL, '[]', 'fill', '["%s", "%e", "%t", "%S"]', NULL, '`%S` 는 0~59 의 초(second) 필드입니다. 두 시각의 차이를 구할 때는 `%s` 끼리 빼세요.', '[0]', 'date +{0}', NULL, NULL),
  (165, 25, '시간 제한 두기', '명령이 **1초 안에 끝나지 않으면 종료**하게 하는 `timeout` 의 인자를 채우세요.', '초 단위 숫자예요.', NULL, NULL, '[]', 'fill', '["1", "-t 1", "--time 1", "=1"]', NULL, '시간 초과로 종료되면 종료 코드가 `124` 입니다. 스크립트에서 `$?` 로 확인할 수 있어요.', '[0]', 'timeout {0} sleep 5', NULL, NULL),
  (165, 26, 'cron 작업을 안전하게 등록하기', '백업 스크립트를 cron 에 등록하고 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '손으로 실행 → 줄 작성 → 등록 → 목록 확인 → 로그 확인 순서예요.', NULL, NULL, '[]', 'order', '["`/usr/local/bin/backup.sh` 를 쉘에서 직접 실행해 정상 동작하는지 확인한다", "절대 경로, `\\\\%` 이스케이프, `>> /var/log/backup.log 2>&1` 를 넣어 crontab 줄을 작성한다", "`crontab -e` 나 `crontab 파일` 로 등록한다 (파일은 마지막 줄 끝에 줄바꿈을 넣는다)", "`crontab -l` 로 등록을 확인하고 실행 시각 이후 로그 파일을 확인한다"]', NULL, '먼저 손으로 실행해 보지 않고 등록하면 cron 문제인지 스크립트 문제인지 구분하기 어렵습니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (165, 27, 'cron 에서만 실패하는 작업 풀기', '터미널에서는 되는데 cron 에서만 실패할 때의 조사 순서입니다. 순서에 맞게 놓아 보세요.', '로그 남기기 → 종료 코드 → 환경 차이 → 고치기 순서예요.', NULL, NULL, '[]', 'order', '["`>> /tmp/job.log 2>&1` 로 출력과 오류가 파일에 남게 한다", "로그의 `not found` 나 종료 코드 127 이 보이면 PATH 문제라고 짐작한다", "명령을 절대 경로로 바꾸고 `%` 이스케이프, 작업 디렉터리(`cd`), 사용하는 쉘(`/bin/sh`)을 점검한다", "다음 실행 시각 이후 로그로 성공을 확인한다"]', NULL, 'cron 의 환경(PATH, 쉘, 작업 디렉터리)이 로그인 쉘과 다르다는 것이 대부분의 원인입니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (165, 28, '두 날짜 사이의 일수 구하기', '`date` 로 2026-02-01 과 2026-03-01 사이의 일수를 구하는 순서입니다. 순서에 맞게 놓아 보세요.', '에포크 구하기 → 빼기 → 하루로 나누기 → 확인 순서예요.', NULL, NULL, '[]', 'order', '["`date -u -d 2026-03-01 +%s` 로 뒤 날짜의 에포크 초를 구한다", "`date -u -d 2026-02-01 +%s` 로 앞 날짜의 에포크 초를 구한다", "두 값을 빼서 86400 으로 나눈다 (`$(( (a - b) / 86400 ))`)", "결과가 28 인지 달력과 비교해 확인한다"]', NULL, '`-u` 로 UTC 를 쓰면 시간대와 서머타임 때문에 하루가 23시간이나 25시간이 되는 오차를 피할 수 있습니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (165, 29, '멈추는 작업을 시간 제한으로 막기', '오래 걸리는 cron 작업이 쌓이지 않게 시간 제한을 두는 순서입니다. 순서에 맞게 놓아 보세요.', '손으로 시간 재기 → 제한 정하기 → 감싸기 → 종료 코드 확인 순서예요.', NULL, NULL, '[]', 'order', '["작업을 직접 실행해 보통 얼마나 걸리는지 `time` 으로 잰다", "그보다 넉넉한 제한 시간(예: 10분)을 정한다", "crontab 줄을 `timeout 600 작업` 형태로 감싼다", "시간 초과로 종료되면 종료 코드가 `124` 인 것을 로그로 확인한다"]', NULL, '제한 시간이 너무 짧으면 정상 작업도 끊깁니다. 평소 소요 시간보다 넉넉하게 정하세요.', '[0, 1, 2, 3]', NULL, NULL, NULL);
